/usr/bin/bash -lc "perl -Mstrict -Mwarnings -MText::ParseWords -e '
use File::Path qw(make_path);
my "'$base="/workspace";
my $trace="$base/run_trace";
my $reads="$base/final_answer/reads";
my $meta="$base/final_answer/metadata";
make_path($meta, $reads);
my @required = qw(bioproject run_accession study_accession experiment_accession sample_accession biosample organism_taxid organism_name library_strategy library_source library_selection library_layout instrument_model run_total_spots run_total_bases);
my @manifest;
my @summary;
my @projects = (["PRJNA1354216", "$trace/downloaded_metadata/PRJNA1354216.pysradb.tsv"], ["PRJNA1339024", "$trace/downloaded_metadata/PRJNA1339024.pysradb.tsv"]);
for my $proj (@projects) {
  my ($bp, $path) = @$proj;
  open my $in, "<", $path or die "open $path: $!";
  chomp(my $header = <$in>);
  my @h = split /'"\\t/, "'$header, -1;
  my %idx; @idx{@h} = (0..$#h);
  my @rows; my %seen;
  while (defined(my $line = <$in>)) {
    chomp $line;
    next if $line =~ /''^'"\\s*"'$/;
    my @f = split /'"\\t/, "'$line, -1;
    my $get = sub { my ($k)=@_; return exists $idx{$k} ? ($f[$idx{$k}] // "") : ""; };
    my $all = join("'"\\t\", @f);
    die \"row not linked to "'$bp'"\\n\" unless index("'$all, $bp) >= 0;
    my $pub = lc $get->("run_1_is_public");
    next if length($pub) && $pub ne "true" && $pub ne "1";
    my $run = $get->("run_1_accession");
    die "missing run accession in $path'"\\n\" unless length "'$run;
    die "duplicate run $run in $bp'"\\n\" if "'$seen{$run}++;
    my $layout = uc $get->("library_layout");
    my %out = (
      bioproject => $bp,
      run_accession => $run,
      study_accession => $get->("study_accession"),
      experiment_accession => $get->("experiment_accession"),
      sample_accession => $get->("sample_accession"),
      biosample => ($get->("pool_external_id") || $get->("sample_external_id_1")),
      organism_taxid => $get->("sample_taxon_id"),
      organism_name => $get->("sample_scientific_name"),
      library_strategy => $get->("experiment_library_strategy"),
      library_source => $get->("experiment_library_source"),
      library_selection => $get->("experiment_library_selection"),
      library_layout => $layout,
      instrument_model => $get->("experiment_instrument_model"),
      run_total_spots => $get->("run_1_total_spots"),
      run_total_bases => $get->("run_1_total_bases"),
    );
    push @rows, '"\\%out;
    my ("'$fp, $rp);
    if ($layout eq "PAIRED") {
      $fp = "reads/${run}_1.fastq.gz"; $rp = "reads/${run}_2.fastq.gz";
      die "missing $fp'"\\n\" unless -s \""'$base/final_answer/$fp";
      die "missing $rp'"\\n\" unless -s \""'$base/final_answer/$rp";
    } elsif ($layout eq "SINGLE") {
      $fp = "reads/${run}.fastq.gz"; $rp = "";
      die "missing $fp'"\\n\" unless -s \""'$base/final_answer/$fp";
    } else { die "unexpected layout $layout for $run'"\\n\"; }
    push @manifest, {bioproject=>"'$bp, run_accession=>$run, library_layout=>$layout, forward_path=>$fp, reverse_path=>$rp};
  }
  close $in;
  open my $outfh, ">", "$meta/$bp.tsv" or die "write $bp.tsv: $!";
  print $outfh join("'"\\t\", @required), \"\\n\";
  for my "'$r (@rows) { print $outfh join("'"\\t\", map { "'$r->{$_} // "" } @required), "'"\\n\"; }
  close "'$outfh;
  push @summary, [$bp, scalar(@rows), (@rows ? $rows[0]{library_layout} : "")];
}
@manifest = sort { $a->{bioproject} cmp $b->{bioproject} || $a->{run_accession} cmp $b->{run_accession} } @manifest;
my %mr; for my $r (@manifest) { die "dup manifest $r->{run_accession}'"\\n\" if "'$mr{$r->{run_accession}}++; }
open my $mf, ">", "$base/final_answer/run_manifest.tsv" or die "write manifest: $!";
my @mh = qw(bioproject run_accession library_layout forward_path reverse_path);
print $mf join("'"\\t\", @mh), \"\\n\";
for my "'$r (@manifest) { print $mf join("'"\\t\", map { "'$r->{$_} // "" } @mh), "'"\\n\"; }
close "'$mf;
open my $lf, ">", "$trace/execution_log.tsv" or die "write log: $!";
print $lf "step'"\\tdetail\\n\";
print "'$lf "assigned_history'"\\tbbd44e69cb8906b5444e24b360c0b4b9\\n\";
print "'$lf "input_bioprojects'"\\tPRJNA1354216,PRJNA1339024\\n\";
print "'$lf "metadata_tool'"\\tpysradb search 2.5.1+galaxy0; verbosity 3; one query per BioProject\\n\";
print "'$lf "read_tool'"\\tfasterq-dump 3.1.1+galaxy1; --split-3; skip_technical=true; input all_sra_runs.txt\\n\";
for my "'$s (@summary) { print $lf "$s->[0]_runs'"\\t"'$s->[1] rows; $s->[2]'"\\n\"; }
my "'$n = () = glob "$reads/*.fastq.gz";
print $lf "fastq_files'"\\t"'$n downloaded Galaxy datasets'"\\n\";
close "'$lf;
'"'
find final_answer -maxdepth 3 -type f | sort | sed -n '1,80p'"

/usr/bin/bash -lc "set -e
# Basic structure and row counts
printf 'metadata rows:\\n' > run_trace/validation_summary.txt
for f in final_answer/metadata/*.tsv; do printf '%s\\t%s\\n' \""'$f" "$(( $(wc -l < "$f") - 1 ))" >> run_trace/validation_summary.txt; done
printf '"'manifest rows:\\t%s\\n' \""'$(( $(wc -l < final_answer/run_manifest.tsv) - 1 ))" >> run_trace/validation_summary.txt
printf '"'fastq files:\\t%s\\n' \""'$(find final_answer/reads -type f -name '"'*.fastq.gz' | wc -l)\" >> run_trace/validation_summary.txt
# gzip integrity
gzip -t final_answer/reads/*.fastq.gz
printf 'gzip_integrity\\tok\\n' >> run_trace/validation_summary.txt
# Manifest paths exist, metadata and manifest run sets match, and FASTQ record counts match spots.
perl -Mstrict -Mwarnings -e '
my "'$base="/workspace/final_answer";
my (%meta, %spots, %layout);
for my $mf (glob "$base/metadata/*.tsv") {
  open my $fh, "<", $mf or die $!;
  chomp(my $h=<$fh>); my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=(0..$#h);
  for my $req (qw(bioproject run_accession study_accession experiment_accession sample_accession biosample organism_taxid organism_name library_strategy library_source library_selection library_layout instrument_model run_total_spots run_total_bases)) { die "missing $req in $mf'"\\n\" unless exists "'$i{$req}; }
  while(<$fh>) { chomp; my @f=split /'"\\t/,"'$_,-1; my $bp=$f[$i{bioproject}]; my $run=$f[$i{run_accession}]; die "bad bioproject in $mf'"\\n\" unless "'$mf =~ /'"\\Q"'$bp'"\\E\\.tsv"'$/; die "dup meta $run'"\\n\" if "'$meta{$run}++; $spots{$run}=$f[$i{run_total_spots}]; $layout{$run}=$f[$i{library_layout}]; }
}
open my $man,"<","$base/run_manifest.tsv" or die $!; chomp(my $mh=<$man>); my @mh=split /'"\\t/,"'$mh,-1; my %mi; @mi{@mh}=(0..$#mh);
for my $req (qw(bioproject run_accession library_layout forward_path reverse_path)) { die "missing manifest $req'"\\n\" unless exists "'$mi{$req}; }
my %man;
while(<$man>) { chomp; my @f=split /'"\\t/,"'$_,-1; my $run=$f[$mi{run_accession}]; die "dup manifest $run'"\\n\" if "'$man{$run}++; die "manifest missing from metadata $run'"\\n\" unless "'$meta{$run}; die "layout mismatch $run'"\\n\" unless "'$layout{$run} eq $f[$mi{library_layout}]; for my $p ($f[$mi{forward_path}], $f[$mi{reverse_path}]) { next unless length $p; die "absolute path $p'"\\n\" if "'$p =~ m{''^/}; die "missing $p'"\\n\" unless -s \""'$base/$p"; } die "single reverse not empty $run'"\\n\" if "'$layout{$run} eq "SINGLE" && length $f[$mi{reverse_path}]; }
for my $run (keys %meta) { die "metadata missing from manifest $run'"\\n\" unless "'$man{$run}; }
'"' 
# Count FASTQ records and compare to spots from manifest/metadata.
perl -Mstrict -Mwarnings -e '
my "'$base="/workspace/final_answer";
my (%spots,%layout);
for my $mf (glob "$base/metadata/*.tsv") { open my $fh,"<",$mf or die $!; chomp(my $h=<$fh>); my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=(0..$#h); while(<$fh>){chomp; my @f=split /'"\\t/,"'$_,-1; $spots{$f[$i{run_accession}]}=$f[$i{run_total_spots}]; $layout{$f[$i{run_accession}]}=$f[$i{library_layout}];} }
open my $out, ">", "/workspace/run_trace/fastq_record_counts.tsv" or die $!; print $out "run_accession'"\\tread\\trecords\\texpected_spots\\n\";
for my "'$run (sort keys %spots) {
  my @files = $layout{$run} eq "PAIRED" ? ([$base."/reads/${run}_1.fastq.gz","forward"],[$base."/reads/${run}_2.fastq.gz","reverse"]) : ([$base."/reads/${run}.fastq.gz","single"]);
  for my $fr (@files) { my ($file,$read)=@$fr; open my $gz, "gzip -cd $file |" or die $!; my $lines=0; $lines++ while <$gz>; close $gz; die "line count not multiple of 4 for $file'"\\n\" if "'$lines % 4; my $rec=$lines/4; print $out "$run'"\\t"'$read'"\\t"'$rec'"\\t"'$spots{$run}'"\\n\"; die \"record count mismatch "'$run $read $rec != $spots{$run}'"\\n\" unless "'$rec == $spots{$run}; }
}
close $out;
'"'
printf 'record_counts_match_spots\\tok\\n' >> run_trace/validation_summary.txt
cat run_trace/validation_summary.txt"
